using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;

[InitializeOnLoad] public static class GridShiftCrossingRegression {
 static GridShiftCrossingRegression(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("CrossingRegression",false)){SessionState.SetBool("CrossingRegression",false);new GameObject("CrossingRegression").AddComponent<GridShiftCrossingRunner>();}};}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)] static void Prepare(){if(SessionState.GetBool("CrossingRegression",false)){DeliverySaveStore.OverridePath=Path.GetFullPath("crossing-"+Guid.NewGuid().ToString("N")+".json");GridShiftTutorial.Prefix="GS.Crossing.Test.";GridShiftTutorial.Skip();}}
 public static void Batch(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");foreach(var w in Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))w.enabled=false;SessionState.SetBool("CrossingRegression",true);EditorApplication.isPlaying=true;}
 public static void Audit(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");Physics.SyncTransforms();var manager=Object.FindFirstObjectByType<PedestrianManager>();string text="";foreach(var c in manager.graph.crossings.Where(c=>Vector3.Distance(c.junction.transform.position,new Vector3(244.1f,-4.6f,261.4f))<1)){var a=manager.graph.nodes[c.a].position;var b=manager.graph.nodes[c.b].position;bool hit=Physics.CapsuleCast(a+Vector3.up*.6f,a+Vector3.up*1.55f,.29f,(b-a).normalized,out var obstacle,Vector3.Distance(a,b),~(1<<9),QueryTriggerInteraction.Ignore);text+="CROSS "+c.a+" "+a+" -> "+c.b+" "+b+" cast="+hit+" "+obstacle.collider?.name+"\n";foreach(var p in new[]{a,b})foreach(var col in Physics.OverlapCapsule(p+Vector3.up*.6f,p+Vector3.up*1.55f,.27f,~(1<<9),QueryTriggerInteraction.Ignore))text+="ENDPOINT "+p+" "+col.name+" "+col.GetType().Name+" "+col.bounds+"\n";}File.WriteAllText("crossing-static.txt",text);EditorApplication.Exit(0);}
 public static void PhysicsChecks(){var report=new System.Text.StringBuilder();try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);TrafficBehaviourChecks.Run();report.AppendLine("PASS 10 testes existentes de trânsito");ShortBlock(20,true,report);ShortBlock(12,false,report);GroupSafety(report);SignalClearance(report);report.AppendLine("RESULT SUCCESS");}catch(Exception e){report.AppendLine("FAIL "+e);}File.WriteAllText("crossing-physics.txt",report.ToString());EditorApplication.Exit(report.ToString().Contains("FAIL")?1:0);}
 static void SignalClearance(System.Text.StringBuilder report){
  var root=new GameObject("SignalClearanceTest");try{
   T Add<T>(string name)where T:Component{var go=new GameObject(name);go.transform.SetParent(root.transform);return go.AddComponent<T>();}
   var h=Add<TrafficLight>("Horizontal");var v=Add<TrafficLight>("Vertical");var hg=Add<TrafficLightGroup>("HG");var vg=Add<TrafficLightGroup>("VG");Set(hg,"semaforos",new[]{h});Set(vg,"semaforos",new[]{v});var controller=root.AddComponent<TrafficIntersection>();Set(controller,"grupoHorizontal",hg);Set(controller,"grupoVertical",vg);
   var j=Add<TrafficJunction>("Junction");var a=Add<PedestrianAgent>("Walker");var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(TrafficIntersection).GetMethod("Start",flags).Invoke(controller,null);typeof(TrafficIntersection).GetField("instance",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,controller);
   Set(controller,"etapa",2);Set(controller,"contador",1.1f);typeof(TrafficIntersection).GetMethod("AplicarEstado",flags).Invoke(controller,null);
   var update=typeof(TrafficIntersection).GetMethod("Update",flags);var car=Add<TrafficCar>("ClearingVehicle");j.TryEnter(car);if(j.TryCross(a))throw new Exception("Pedestre admitido antes da saída do veículo");j.Release(car);if(!j.TryCross(a))throw new Exception("Travessia não abre após veículo sair");Set(controller,"contador",4.1f);
   update.Invoke(controller,null);if(v.PodePassar()||h.PodePassar()||TrafficIntersection.PedestrianAdmissionOpen)throw new Exception("Verde ou novo grupo durante liberação da faixa");
   j.LeaveCrossing(a);update.Invoke(controller,null);if(!v.PodePassar()||(float)typeof(TrafficIntersection).GetField("contador",flags).GetValue(controller)!=0)throw new Exception("Não iniciou verde completo após saída do último pedestre");report.AppendLine("PASS vermelho mantido durante travessia; novos grupos encerrados; verde completo começa após faixa livre");
  }finally{Object.DestroyImmediate(root);}
 }
 static void Set(object value,string field,object data)=>value.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(value,data);
 static void ShortBlock(float release,bool expectBlocked,System.Text.StringBuilder report){var root=new GameObject("ShortBlockTest");var old=Physics.simulationMode;Physics.simulationMode=SimulationMode.Script;try{
  Transform Point(string name,float z){var go=new GameObject(name);go.transform.SetParent(root.transform);go.transform.position=Vector3.forward*z;return go.transform;}
  TrafficRoute Route(float start,float end,float center,TrafficLight.Estado state,out TrafficJunction junction,out TrafficLight signal){var r=Point("Route",0).gameObject.AddComponent<TrafficRoute>();r.pontos=new[]{Point("Start",start),Point("End",end)};junction=Point("Junction",center).gameObject.AddComponent<TrafficJunction>();signal=Point("Signal",0).gameObject.AddComponent<TrafficLight>();signal.DefinirEstado(state);Set(r,"cruzamento",junction);Set(r,"semaforo",signal);Set(r,"linhaParada",Point("Stop",center-12));Set(r,"saidaCruzamento",Point("Exit",end));return r;}
  var first=Route(0,60,40,TrafficLight.Estado.Verde,out var j1,out _);Route(60,100,80,TrafficLight.Estado.Vermelho,out _,out var light2);Set(j1,"crossingExit",release);
  var body=Point("Vehicle",0).gameObject;var box=body.AddComponent<BoxCollider>();box.size=new Vector3(2,2,14);box.center=Vector3.up*1.1f;var car=body.AddComponent<TrafficCar>();car.ConfigureProfile(box,false,8,2,4);car.ResetRoute(first);var update=typeof(TrafficCar).GetMethod("FixedUpdate",BindingFlags.NonPublic|BindingFlags.Instance);Physics.SyncTransforms();
  for(int i=0;i<2000;i++){update.Invoke(car,null);Physics.Simulate(.02f);}float stopped=body.transform.position.z;if(stopped<57||stopped>65)throw new Exception("Parada no segundo vermelho inválida: "+stopped);
  light2.DefinirEstado(TrafficLight.Estado.Verde);for(int i=0;i<1000;i++){update.Invoke(car,null);Physics.Simulate(.02f);}float moved=body.transform.position.z-stopped;
  if(expectBlocked){if(moved>.1f)throw new Exception("Fixture antiga não reproduziu bloqueio");report.AppendLine("BASELINE reserva de 20 m reproduz carro parado no segundo verde");}
  else{if(moved<20)throw new Exception("Veículo não retomou no segundo verde: "+moved);report.AppendLine("PASS cruzamentos separados por 40 m: vermelho respeitado, reserva anterior liberada e retomada no verde");}
 }finally{Object.DestroyImmediate(root);Physics.simulationMode=old;Physics.SyncTransforms();}}
 static void GroupSafety(System.Text.StringBuilder report){var root=new GameObject("GroupTest");try{var j=root.AddComponent<TrafficJunction>();PedestrianAgent Agent(){var g=new GameObject("Pedestrian");g.transform.SetParent(root.transform);return g.AddComponent<PedestrianAgent>();}var a=Agent();var b=Agent();var opposite=Agent();var v=new GameObject("Car");v.transform.SetParent(root.transform);var car=v.AddComponent<TrafficCar>();
  if(!j.TryCross(a,1,2)||!j.TryCross(b,1,2)||j.TryCross(opposite,2,1))throw new Exception("Grupo admitiu fluxos conflitantes");j.LeaveCrossing(a);if(j.TryEnter(car)||!j.PedestrianOccupied)throw new Exception("Reserva liberada antes do último pedestre");j.LeaveCrossing(b);if(!j.TryEnter(car))throw new Exception("Veículo não recuperou acesso após grupo");report.AppendLine("PASS grupo da mesma direção, fluxo oposto bloqueado e reserva mantida até o último pedestre");
 }finally{Object.DestroyImmediate(root);}}
}
public sealed class GridShiftCrossingRunner:MonoBehaviour {
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 readonly List<PedestrianAgent> testAgents=new List<PedestrianAgent>();
 IEnumerator Start(){Time.timeScale=3;Application.runInBackground=true;yield return new WaitForSeconds(2);var environment=Object.FindFirstObjectByType<CityEnvironment>();if(environment!=null)environment.enabled=false;GridShiftPerformanceSettings.Set("Traffic",1);Object.FindFirstObjectByType<TrafficManager>().SetRoutineDensity(1);var manager=Object.FindFirstObjectByType<PedestrianManager>();manager.StopAllCoroutines();foreach(var agent in manager.Agents.ToArray())manager.Recycle(agent);
 var building=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.IndexOf("Clothing",StringComparison.OrdinalIgnoreCase)>=0).First();
 var junction=Object.FindObjectsByType<TrafficJunction>(FindObjectsSortMode.None).OrderBy(j=>(j.transform.position-building.bounds.center).sqrMagnitude).First();
 var crossings=manager.graph.crossings.Where(c=>c.junction==junction).ToArray();File.WriteAllText("crossing-trace.txt","BUILDING "+building.name+" "+building.bounds+" JUNCTION "+junction.transform.position+" crossings="+crossings.Length+"\n");
 foreach(var crossing in crossings.Take(2))for(int side=0;side<2;side++)for(int count=0;count<2;count++){
  int from=side==0?crossing.a:crossing.b,to=side==0?crossing.b:crossing.a;var away=(manager.graph.nodes[from].position-manager.graph.nodes[to].position).normalized;var desired=manager.graph.nodes[from].position+away*(count*1.5f+1);
  int node=Enumerable.Range(0,manager.graph.nodes.Length).Where(i=>!manager.graph.nodes[i].entrancePath&&Vector3.Distance(manager.graph.nodes[i].position,desired)<3&&manager.Clear(null,manager.graph.nodes[i].position,1)).OrderBy(i=>(manager.graph.nodes[i].position-desired).sqrMagnitude).DefaultIfEmpty(-1).First();if(node<0)continue;
  var go=Object.Instantiate(manager.models[count%manager.models.Length],manager.transform);go.name="CrossingTest_"+testAgents.Count;var agent=go.AddComponent<PedestrianAgent>();agent.Initialize(manager,node,1.1f);((List<PedestrianAgent>)manager.Agents).Add(agent);agent.WalkTo(to);testAgents.Add(agent);
 }
 float until=Time.time+240,next=0,occupiedSince=0,maxHold=0;var admissions=new HashSet<TrafficCar>();int horizontal=0,vertical=0;while(Time.time<until){
 if(junction.PedestrianOccupied){if(occupiedSince==0)occupiedSince=Time.time;maxHold=Mathf.Max(maxHold,Time.time-occupiedSince);}else occupiedSince=0;
 var owner=(TrafficCar)typeof(TrafficJunction).GetField("owner",Flags).GetValue(junction);if(owner!=null&&admissions.Add(owner)&&owner.RotaAtual.GetParada(out _,out var direction)){if(Mathf.Abs(direction.x)>.5f)horizontal++;else vertical++;}
 if(Time.time>next){next=Time.time+5;string text="TIME "+Time.time+" owner="+((TrafficCar)typeof(TrafficJunction).GetField("owner",Flags).GetValue(junction))?.name+" pedestrian="+((PedestrianAgent)typeof(TrafficJunction).GetField("pedestrian",Flags).GetValue(junction))?.name+"\n";
 foreach(var a in testAgents.Where(a=>a!=null&&a.gameObject.activeSelf)){int current=(int)typeof(PedestrianAgent).GetField("current",Flags).GetValue(a);var crossing=(PedestrianCrossing)typeof(PedestrianAgent).GetField("crossing",Flags).GetValue(a);text+=a.name+" "+a.transform.position+" "+a.CurrentActivity+" current="+current+" next="+a.NextNode+" target="+(a.NextNode>=0?manager.graph.nodes[a.NextNode].position.ToString():"none")+" cross="+(crossing!=null)+" blocker="+a.Obstacle?.name+" crossings="+a.CrossingsCompleted+" blocked="+typeof(PedestrianAgent).GetField("blockedTime",Flags).GetValue(a)+" approach="+typeof(PedestrianAgent).GetField("approachBlocked",Flags).GetValue(a)+" plan="+typeof(PedestrianAgent).GetField("approachPlanned",Flags).GetValue(a)+" goal="+typeof(PedestrianAgent).GetField("approachGoal",Flags).GetValue(a)+" exitClear="+(crossing!=null&&a.NextNode>=0?manager.CrossingClear(a,current,a.NextNode):false)+"\n";}
 foreach(var car in TrafficCar.Active.Where(c=>c!=null&&(c.transform.position-junction.transform.position).sqrMagnitude<35*35))text+="CAR "+car.name+" "+car.transform.position+" "+car.Diagnostic+" blocker="+car.Obstacle?.name+"\n";File.AppendAllText("crossing-trace.txt",text);}yield return null;}
 int completed=testAgents.Count(a=>a!=null&&a.CrossingsCompleted>0);var traffic=Object.FindFirstObjectByType<TrafficManager>();bool success=completed>=7&&maxHold<35&&horizontal>0&&vertical>0&&traffic.ActiveCount>=20;
 File.WriteAllText("crossing-result.txt","Agents="+testAgents.Count+" unique_crossers="+completed+" crossings="+testAgents.Sum(a=>a!=null?a.CrossingsCompleted:0)+" max_hold_seconds="+maxHold+" horizontal_vehicles="+horizontal+" vertical_vehicles="+vertical+" ambient_vehicles="+traffic.ActiveCount+" target="+traffic.TargetCount+"\nRESULT "+(success?"SUCCESS":"FAILURE"));EditorApplication.Exit(success?0:1);
 }
}
